import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { Plus, Minus } from "lucide-react";
import JewelArt from "./JewelArt";
import Reveal from "./Reveal";
import { COLORS, FONT_DISPLAY } from "../constants/theme";
import { money } from "../utils/helpers";
import { fetchProducts, fetchCategories } from "../data/products";

export default function Shop({ filter, setFilter, cart, addToCart, updateQty }) {
  const [products, setProducts] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Fetch categories once on mount
  useEffect(() => {
    let cancelled = false;
    fetchCategories()
      .then((data) => {
        if (!cancelled) setCategories(data);
      })
      .catch(() => {
        if (!cancelled) setCategories([]);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  // Fetch products whenever the selected filter changes
  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);

    // filter is either "All" or a categoryId (number/string) now, not a name
    const categoryId = filter === "All" ? undefined : filter;

    fetchProducts({ categoryId })
      .then((data) => {
        if (!cancelled) setProducts(data.content);
      })
      .catch((err) => {
        if (!cancelled) setError(err.message);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [filter]);

  // Reads live quantity straight from the shared cart, so this stays in sync
  // with the cart drawer and product detail page without any local copy.
  const qtyInCart = (productId) => cart.find((item) => item.id === productId)?.qty || 0;

  const increment = (e, p) => {
    e.preventDefault();
    e.stopPropagation();

    const inStock = typeof p.stockQuantity === "number" ? p.stockQuantity : Infinity;
    const current = qtyInCart(p.id);

    if (current >= inStock) return; // can't add past available stock

    if (current === 0) {
      addToCart(p);
    } else {
      updateQty(p.id, 1);
    }
  };

  const decrement = (e, p) => {
    e.preventDefault();
    e.stopPropagation();

    const current = qtyInCart(p.id);
    if (current <= 0) return;

    updateQty(p.id, -1);
  };

  return (
    <section
      id="shop"
      style={{ background: COLORS.surfaceSoft }}
      className="px-4 sm:px-6 md:px-10 py-16 md:py-[100px]"
    >
      <style>{`
        @keyframes shop-qty-in {
          from { opacity: 0; transform: scale(0.85); }
          to { opacity: 1; transform: scale(1); }
        }
        .shop-qty-control {
          animation: shop-qty-in 0.28s cubic-bezier(0.22, 1, 0.36, 1);
        }
        .shop-add-btn {
          transition: background 0.2s ease, transform 0.15s ease, opacity 0.28s ease;
        }
        .shop-add-btn:active:not(:disabled) {
          transform: scale(0.9);
        }
        .shop-qty-btn {
          transition: background 0.2s ease, transform 0.15s ease;
        }
        .shop-qty-btn:hover:not(:disabled) {
          background: ${COLORS.surfaceSoft};
        }
        .shop-qty-btn:active:not(:disabled) {
          transform: scale(0.88);
        }
        .shop-qty-count {
          display: inline-block;
          transition: transform 0.18s ease;
        }
      `}</style>

      <div style={{ maxWidth: 1240, margin: "0 auto" }}>
        <Reveal>
          <div className="flex flex-col md:flex-row md:items-end md:justify-between" style={{ gap: 20, marginBottom: 50 }}>
            <div>
              <p style={{ fontSize: 13, letterSpacing: "0.2em", textTransform: "uppercase", color: COLORS.rust, marginBottom: 14 }}>
                The shop
              </p>
              <h2 style={{ fontFamily: FONT_DISPLAY, fontSize: "clamp(28px, 4vw, 44px)" }}>Current pieces</h2>
            </div>
            <div className="mobile-pill-row" style={{ gap: 10 }}>
              <button
                onClick={() => setFilter("All")}
                style={{
                  border: `1px solid ${filter === "All" ? COLORS.surfaceStrong : COLORS.border}`,
                  background: filter === "All" ? COLORS.surfaceStrong : "transparent",
                  color: filter === "All" ? COLORS.textOnStrong : COLORS.text,
                  padding: "12px 18px",
                  fontSize: 13,
                  letterSpacing: "0.03em",
                }}
              >
                All
              </button>
              {categories.map((c) => (
                <button
                  key={c.id}
                  onClick={() => setFilter(c.id)}
                  style={{
                    border: `1px solid ${filter === c.id ? COLORS.surfaceStrong : COLORS.border}`,
                    background: filter === c.id ? COLORS.surfaceStrong : "transparent",
                    color: filter === c.id ? COLORS.textOnStrong : COLORS.text,
                    padding: "9px 18px",
                    fontSize: 13,
                    letterSpacing: "0.03em",
                  }}
                >
                  {c.name}
                </button>
              ))}
            </div>
          </div>
        </Reveal>

        {loading && <p style={{ padding: "20px 0" }}>Loading products…</p>}
        {error && <p style={{ padding: "20px 0", color: "crimson" }}>Couldn't load products: {error}</p>}

        {!loading && !error && (
          <div className="shop-grid grid grid-cols-2 md:grid-cols-4">
            {products.map((p, i) => {
              const qty = qtyInCart(p.id);
              const inStock = typeof p.stockQuantity === "number" ? p.stockQuantity : Infinity;
              const outOfStock = inStock <= 0;
              const atMax = qty >= inStock;

              return (
                <Reveal key={p.id} delay={(i % 4) * 60}>
                  <Link
                    to={`/product/${p.id}`}
                    style={{
                      background: COLORS.surfaceCard,
                      border: `1px solid ${COLORS.border}`,
                      display: "flex",
                      flexDirection: "column",
                      height: "100%",
                      textDecoration: "none",
                      color: "inherit",
                    }}
                  >
                    <div
                      style={{
                        aspectRatio: "1 / 1",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        borderBottom: `1px solid ${COLORS.border}`,
                        position: "relative",
                        overflow: "hidden",
                      }}
                    >
                      {p.imageUrl && p.imageUrl.length > 0 ? (
                        <img
                          src={p.imageUrl[0]}
                          alt={p.name}
                          style={{ width: "100%", height: "100%", objectFit: "cover" }}
                        />
                      ) : (
                        <JewelArt type={p.art} style={{ width: "42%", color: COLORS.verdigris }} />
                      )}
                      <span
                        style={{
                          position: "absolute",
                          top: 10,
                          left: 10,
                          fontSize: 10.5,
                          letterSpacing: "0.1em",
                          textTransform: "uppercase",
                          color: COLORS.rust,
                        }}
                      >
                        {p.categoryName}
                      </span>
                      {outOfStock && (
                        <span
                          style={{
                            position: "absolute",
                            top: 10,
                            right: 10,
                            fontSize: 10.5,
                            letterSpacing: "0.08em",
                            textTransform: "uppercase",
                            color: "#fff",
                            background: "crimson",
                            padding: "3px 8px",
                            borderRadius: 3,
                          }}
                        >
                          Out of stock
                        </span>
                      )}
                    </div>
                    <div style={{ padding: "14px 14px 16px", display: "flex", flexDirection: "column", flex: 1 }}>
                      <h4 style={{ fontFamily: FONT_DISPLAY, fontSize: "clamp(15px, 4vw, 18px)", marginBottom: 4 }}>
                        {p.name}
                      </h4>
                      <p style={{ fontSize: 12.5, color: COLORS.textSoft, marginBottom: 14 }}>{p.material}</p>
                      <div
                        className="flex items-center justify-between"
                        style={{ marginTop: "auto", position: "relative", height: 40 }}
                      >
                        <span style={{ fontSize: 15 }}>{money(p.price)}</span>

                        {/* Both controls are kept mounted and cross-fade/scale between
                            each other so the swap reads as a smooth transition,
                            not an instant pop. */}
                        <div style={{ position: "relative", width: 40, height: 40 }}>
                          <button
                            onClick={(e) => increment(e, p)}
                            disabled={outOfStock}
                            aria-label={`Add ${p.name} to cart`}
                            className="mobile-touch-target shop-add-btn"
                            style={{
                              position: "absolute",
                              inset: 0,
                              width: 40,
                              height: 40,
                              borderRadius: "50%",
                              background: outOfStock ? COLORS.border : COLORS.surfaceStrong,
                              color: outOfStock ? COLORS.textSoft : COLORS.textOnStrong,
                              border: "none",
                              display: "flex",
                              alignItems: "center",
                              justifyContent: "center",
                              cursor: outOfStock ? "not-allowed" : "pointer",
                              opacity: qty === 0 ? 1 : 0,
                              transform: qty === 0 ? "scale(1)" : "scale(0.85)",
                              pointerEvents: qty === 0 ? "auto" : "none",
                            }}
                          >
                            <Plus size={15} />
                          </button>

                          <div
                            className="flex items-center"
                            style={{
                              position: "absolute",
                              right: 0,
                              top: "50%",
                              transform: qty === 0 ? "translateY(-50%) scale(0.85)" : "translateY(-50%) scale(1)",
                              gap: 2,
                              border: `1px solid ${COLORS.surfaceStrong}`,
                              borderRadius: 20,
                              padding: 2,
                              background: COLORS.surfaceCard,
                              opacity: qty === 0 ? 0 : 1,
                              pointerEvents: qty === 0 ? "none" : "auto",
                              transition: "opacity 0.28s cubic-bezier(0.22, 1, 0.36, 1), transform 0.28s cubic-bezier(0.22, 1, 0.36, 1)",
                            }}
                          >
                            <button
                              onClick={(e) => decrement(e, p)}
                              aria-label={`Remove one ${p.name} from cart`}
                              className="mobile-touch-target shop-qty-btn"
                              style={{
                                width: 30,
                                height: 30,
                                minWidth: 30,
                                borderRadius: "50%",
                                background: "transparent",
                                color: COLORS.surfaceStrong,
                                border: "none",
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                                cursor: "pointer",
                              }}
                            >
                              <Minus size={13} />
                            </button>

                            <span
                              key={qty}
                              className="shop-qty-count"
                              style={{
                                minWidth: 18,
                                textAlign: "center",
                                fontSize: 13.5,
                              }}
                            >
                              {qty}
                            </span>

                            <button
                              onClick={(e) => increment(e, p)}
                              disabled={atMax}
                              aria-label={`Add one more ${p.name} to cart`}
                              className="mobile-touch-target shop-qty-btn"
                              style={{
                                width: 30,
                                height: 30,
                                minWidth: 30,
                                borderRadius: "50%",
                                background: atMax ? COLORS.border : COLORS.surfaceStrong,
                                color: atMax ? COLORS.textSoft : COLORS.textOnStrong,
                                border: "none",
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                                cursor: atMax ? "not-allowed" : "pointer",
                              }}
                            >
                              <Plus size={13} />
                            </button>
                          </div>
                        </div>
                      </div>
                      {qty > 0 && atMax && (
                        <p style={{ fontSize: 11, color: COLORS.textSoft, marginTop: 6, textAlign: "right" }}>
                          Max stock reached
                        </p>
                      )}
                    </div>
                  </Link>
                </Reveal>
              );
            })}
          </div>
        )}
      </div>
    </section>
  );
}
